changeSet.sql:
create or replace function ledger_entry_append_only() returns trigger as $$
begin
    if coalesce(current_setting('zaramoney.ledger_maintenance', true), '') = 'on' then
        if tg_level = 'STATEMENT' then
            return null;
        elsif tg_op = 'DELETE' then
            return old;
        end if;
        return new;
    end if;
    raise exception 'ledger_entry is append-only: % is not allowed', tg_op
        using errcode = 'P0001', hint = 'Post a correcting transaction instead';
end;
$$ language plpgsql;

create trigger trg_ledger_entry_append_only
    before update or delete on ledger_entry
    for each row execute procedure ledger_entry_append_only();

create trigger trg_ledger_entry_no_truncate
    before truncate on ledger_entry
    for each statement execute procedure ledger_entry_append_only();

rollback.sql:
drop trigger if exists trg_ledger_entry_no_truncate on ledger_entry;
drop trigger if exists trg_ledger_entry_append_only on ledger_entry;
drop function if exists ledger_entry_append_only();
